const wm = new WeakMap();
const sesja = {};

wm.set(sesja, "token-abc");
console.log(wm.get(sesja)); // "token-abc"

const metadaneMap = new WeakMap();

function ustawMetadane(obiekt, dane) {
  metadaneMap.set(obiekt, dane);
}

function odczytajMetadane(obiekt) {
  return metadaneMap.get(obiekt);
}

const element = { id: 5 };
ustawMetadane(element, { widoczny: true });
console.log(odczytajMetadane(element)); // { widoczny: true }

// Dwie kluczowe roznice miedzy WeakMap a zwykla Map:
// 1. Iterowalnosc: Map jest iterowalna (for...of, .keys(), .values(),
//    .entries(), .size), WeakMap NIE jest iterowalna w zaden sposob -
//    brak mozliwosci "wylistowania" wszystkich kluczy/wartosci.
// 2. Dopuszczalne typy kluczy: Map przyjmuje klucz DOWOLNEGO typu
//    (string, liczba, boolean, obiekt), WeakMap wymaga, aby klucz
//    BYL ZAWSZE obiektem - proba uzycia stringa/liczby jako klucza
//    rzuca blad TypeError.

const zablokowaniUzytkownicy = new WeakSet();
const uzytkownikA = {};
const uzytkownikB = {};

zablokowaniUzytkownicy.add(uzytkownikA);

console.log(zablokowaniUzytkownicy.has(uzytkownikA)); // true
console.log(zablokowaniUzytkownicy.has(uzytkownikB)); // false

const ws = new WeakSet();
// ws.add("test"); -- TypeError: Invalid value used in weak set
// WeakSet wymaga, aby kazda przechowywana wartosc byla obiektem - string
// "test" nie moze zostac dodany, poniewaz "slaba" referencja ma sens
// wylacznie dla obiektow (podlegajacych mechanizmowi garbage collection
// w sposob, w jaki nie podlegaja mu wartosci prymitywne jak string).

function jestPrzetworzonyElement(element, przetworzoneWeakSet) {
  return przetworzoneWeakSet.has(element);
}

function oznaczJakoPrzetworzony(element, przetworzoneWeakSet) {
  przetworzoneWeakSet.add(element);
}

const przetworzone = new WeakSet();
const element = { id: 1 };

console.log(jestPrzetworzonyElement(element, przetworzone)); // false
oznaczJakoPrzetworzony(element, przetworzone);
console.log(jestPrzetworzonyElement(element, przetworzone)); // true

// WeakMap jest bezpieczniejszym wyborem dla metadanych powiazanych z
// elementami DOM, poniewaz elementy DOM MOGA zostac usuniete ze strony
// w DOWOLNYM momencie (np. przez usuniecie komponentu, zmiane widoku).
//
// Gdyby uzyc zwyklej Map, KAZDY element DOM, ktory kiedykolwiek trafil
// jako klucz do tej Map, pozostalby w pamieci NA ZAWSZE (Map trzyma
// "silna" referencje) - nawet po usunieciu go ze strony, przegladarka
// NIE MOGLABY zwolnic pamieci zajmowanej przez ten element, co
// prowadziloby do STOPNIOWEGO WYCIEKU pamieci w dlugo dzialajacej
// aplikacji.
//
// WeakMap trzyma "slaba" referencje - gdy element DOM zostaje usuniety
// i NIE JEST juz uzywany nigdzie indziej, garbage collector moze go
// bezpiecznie zwolnic, a odpowiadajacy mu wpis w WeakMap znika
// AUTOMATYCZNIE, bez potrzeby recznego sprzatania.
